// Leer la respuesta del agente.
const salida = $input.first().json.output;

let resultado;

if (typeof salida === 'string') {
  try {
    resultado = JSON.parse(salida.trim());
  } catch {
    throw new Error('El agente no devolvió un JSON válido.');
  }
} else {
  resultado = salida;
}

// Comprobar la estructura básica.
if (!resultado || typeof resultado !== 'object') {
  throw new Error('La respuesta del agente está vacía o no es válida.');
}

const estados = ['recopilando', 'listo', 'sin_registro'];

if (!estados.includes(resultado.estado)) {
  throw new Error('El agente devolvió un estado no permitido.');
}

if (!resultado.lead || typeof resultado.lead !== 'object') {
  throw new Error('La respuesta del agente no contiene el objeto lead.');
}

// Aceptar texto o null, sin convertir objetos en datos del lead.
function texto(valor, campo) {
  if (valor === null || valor === undefined) return '';

  if (typeof valor !== 'string') {
    throw new Error(`El campo ${campo} debe ser texto o null.`);
  }

  return valor.trim();
}

const lead = resultado.lead;

// Los metadatos se obtienen del evento real, no de la IA.
const body = $('Webhook Telegram').first().json.body;
const msg = body?.message;

if (!msg?.chat?.id) {
  throw new Error('El evento recibido no contiene un chat de Telegram.');
}

return [{
  json: {
    nombre: texto(lead.nombre, 'nombre'),
    correo: texto(lead.correo, 'correo').toLowerCase(),
    interes: texto(lead.interes, 'interes').toUpperCase(),
    mensaje: texto(lead.mensaje, 'mensaje'),

    canal: 'Telegram',
    chat_id: msg.chat.id,
    update_id: body.update_id ?? null,
    submittedAt: msg.date
      ? new Date(msg.date * 1000).toISOString()
      : new Date().toISOString(),
    formMode: 'telegram',

    estado: resultado.estado,
    respuesta_usuario: texto(
      resultado.respuesta_usuario,
      'respuesta_usuario'
    )
  }
}];

